// Generated by tools/gen-sketches.mjs from sketches/. The kit sketches, built into the app.
window.SKETCHES = {"board_monitor_starter":"// Starter sketch for the Elegoo kit's Arduino UNO R4 WiFi.\n// Prints one line of name=value pairs every 200 ms so Board Monitor can plot it,\n// and answers a few text commands sent from the page.\n//\n// Wiring (change to match your build):\n//   A0  potentiometer middle pin\n//   A1  photoresistor + 10k resistor divider\n//   A2  thermistor + 10k resistor divider\n\nconst unsigned long PERIOD_MS = 200;\nunsigned long lastSend = 0;\nbool streaming = true;\nString cmd;\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(LED_BUILTIN, OUTPUT);\n  while (!Serial && millis() < 3000) {}\n  Serial.println(\"UNO R4 ready. Commands: led on, led off, stop, start, help\");\n}\n\nvoid handleCommand(String c) {\n  c.trim();\n  c.toLowerCase();\n  if (c == \"led on\")       { digitalWrite(LED_BUILTIN, HIGH); Serial.println(\"ok led on\"); }\n  else if (c == \"led off\") { digitalWrite(LED_BUILTIN, LOW);  Serial.println(\"ok led off\"); }\n  else if (c == \"stop\")    { streaming = false; Serial.println(\"ok stopped\"); }\n  else if (c == \"start\")   { streaming = true;  Serial.println(\"ok started\"); }\n  else if (c == \"help\")    { Serial.println(\"Commands: led on, led off, stop, start, help\"); }\n  else if (c.length())     { Serial.print(\"unknown command: \"); Serial.println(c); }\n}\n\nvoid loop() {\n  while (Serial.available()) {\n    char ch = Serial.read();\n    if (ch == '\\n' || ch == '\\r') { handleCommand(cmd); cmd = \"\"; }\n    else if (cmd.length() < 64) cmd += ch;\n  }\n\n  if (streaming && millis() - lastSend >= PERIOD_MS) {\n    lastSend = millis();\n    Serial.print(\"pot=\");    Serial.print(analogRead(A0));\n    Serial.print(\",light=\"); Serial.print(analogRead(A1));\n    Serial.print(\",therm=\"); Serial.println(analogRead(A2));\n  }\n}\n","button":"// Push button on D2, other leg to GND (uses the internal pull-up)\nconst int BTN = 2;\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(BTN, INPUT_PULLUP);\n}\n\nvoid loop() {\n  Serial.print(\"button=\");\n  Serial.println(digitalRead(BTN) == LOW ? 1 : 0);\n  delay(100);\n}\n","buzzer_active":"// Active buzzer on D8. Send \"beep\".\nconst int BZ = 8;\nunsigned long until = 0;\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(BZ, OUTPUT);\n}\n\nvoid loop() {\n  if (Serial.available()) {\n    String c = Serial.readStringUntil('\\n');\n    c.trim();\n    if (c == \"beep\") until = millis() + 300;\n  }\n  bool on = millis() < until;\n  digitalWrite(BZ, on ? HIGH : LOW);\n  Serial.print(\"buzz=\");\n  Serial.println(on ? 1 : 0);\n  delay(50);\n}\n","buzzer_passive":"// Passive buzzer on D8. Send \"tone 440\" or \"stop\".\nconst int BZ = 8;\nint freq = 0;\n\nvoid setup() {\n  Serial.begin(115200);\n}\n\nvoid loop() {\n  if (Serial.available()) {\n    String c = Serial.readStringUntil('\\n');\n    c.trim();\n    if (c.startsWith(\"tone \")) freq = c.substring(5).toInt();\n    if (c == \"stop\") freq = 0;\n    if (freq > 0) tone(BZ, freq); else noTone(BZ);\n  }\n  Serial.print(\"freq=\");\n  Serial.println(freq);\n  delay(200);\n}\n","dht11":"// DHT11 data on D4\n#include <DHT.h>\n\nDHT dht(4, DHT11);\n\nvoid setup() {\n  Serial.begin(115200);\n  dht.begin();\n}\n\nvoid loop() {\n  delay(2000);\n  float h = dht.readHumidity();\n  float t = dht.readTemperature();\n  if (isnan(h) || isnan(t)) {\n    Serial.println(\"DHT11 read failed, check wiring\");\n    return;\n  }\n  Serial.print(\"temp_c=\"); Serial.print(t, 1);\n  Serial.print(\",hum=\");   Serial.println(h, 0);\n}\n","fan":"// Fan motor switched by a PN2222 on D3 (via 1k). Send \"speed <0-255>\".\nconst int FAN = 3;\nint speed = 0;\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(FAN, OUTPUT);\n}\n\nvoid loop() {\n  if (Serial.available()) {\n    String c = Serial.readStringUntil('\\n');\n    c.trim();\n    if (c.startsWith(\"speed \")) speed = constrain(c.substring(6).toInt(), 0, 255);\n  }\n  analogWrite(FAN, speed);\n  Serial.print(\"speed=\");\n  Serial.println(speed);\n  delay(200);\n}\n","imu":"// MPU-6500 on I2C (address 0x68), read directly with Wire\n#include <Wire.h>\n\nconst uint8_t IMU_ADDR = 0x68;   // (the name MPU is taken by the R4 core)\n\nint16_t read16() {\n  uint8_t hi = Wire.read();\n  uint8_t lo = Wire.read();\n  return (int16_t)((hi << 8) | lo);\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  Wire.begin();\n  Wire.beginTransmission(IMU_ADDR);\n  Wire.write(0x6B);   // power management: wake up\n  Wire.write(0);\n  Wire.endTransmission();\n}\n\nvoid loop() {\n  Wire.beginTransmission(IMU_ADDR);\n  Wire.write(0x3B);   // first data register\n  Wire.endTransmission(false);\n  Wire.requestFrom(IMU_ADDR, (size_t)14);\n  float ax = read16() / 16384.0, ay = read16() / 16384.0, az = read16() / 16384.0;\n  read16();           // skip temperature\n  float gx = read16() / 131.0, gy = read16() / 131.0, gz = read16() / 131.0;\n  Serial.print(\"ax=\");  Serial.print(ax, 2);\n  Serial.print(\",ay=\"); Serial.print(ay, 2);\n  Serial.print(\",az=\"); Serial.print(az, 2);\n  Serial.print(\",gx=\"); Serial.print(gx, 1);\n  Serial.print(\",gy=\"); Serial.print(gy, 1);\n  Serial.print(\",gz=\"); Serial.println(gz, 1);\n  delay(100);\n}\n","ir_rx":"// IR receiver signal on D11\n#include <IRremote.hpp>\n\nconst int IR_PIN = 11;\n\nvoid setup() {\n  Serial.begin(115200);\n  IrReceiver.begin(IR_PIN, ENABLE_LED_FEEDBACK);\n  Serial.println(\"Point the remote at the receiver and press a button\");\n}\n\nvoid loop() {\n  if (IrReceiver.decode()) {\n    if (IrReceiver.decodedIRData.protocol != UNKNOWN) {\n      Serial.print(\"ir_cmd=\");\n      Serial.println(IrReceiver.decodedIRData.command);\n    }\n    IrReceiver.resume();\n  }\n}\n","ir_tx":"// IR emitter on D3. Send \"send <command>\".\n#include <IRremote.hpp>\n\nvoid setup() {\n  Serial.begin(115200);\n  IrSender.begin(3);\n}\n\nvoid loop() {\n  if (Serial.available()) {\n    String c = Serial.readStringUntil('\\n');\n    c.trim();\n    if (c.startsWith(\"send \")) {\n      int cmd = c.substring(5).toInt();\n      IrSender.sendNEC(0x00, cmd, 0);\n      Serial.print(\"sent=\");\n      Serial.println(cmd);\n    }\n  }\n}\n","joystick":"// Joystick: VRx on A0, VRy on A1, SW on D2\nconst int SW = 2;\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(SW, INPUT_PULLUP);\n}\n\nvoid loop() {\n  Serial.print(\"x=\");   Serial.print(analogRead(A0));\n  Serial.print(\",y=\");  Serial.print(analogRead(A1));\n  Serial.print(\",sw=\"); Serial.println(digitalRead(SW) == LOW ? 1 : 0);\n  delay(100);\n}\n","keypad":"// 4x4 keypad: rows on D9-D6, columns on D5-D2\n#include <Keypad.h>\n\nconst byte ROWS = 4, COLS = 4;\nchar keys[ROWS][COLS] = {\n  {'1','2','3','A'},\n  {'4','5','6','B'},\n  {'7','8','9','C'},\n  {'*','0','#','D'}\n};\nbyte rowPins[ROWS] = {9, 8, 7, 6};\nbyte colPins[COLS] = {5, 4, 3, 2};\nKeypad pad = Keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);\n\nvoid setup() {\n  Serial.begin(115200);\n}\n\nvoid loop() {\n  char k = pad.getKey();\n  if (k) {\n    Serial.print(\"key=\");\n    Serial.println(k);\n  }\n}\n","l293d":"// L293D: EN on D5 (PWM), IN1 on D4, IN2 on D3. Send \"speed <-255..255>\".\nconst int EN = 5, IN1 = 4, IN2 = 3;\nint speed = 0;\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(EN, OUTPUT);\n  pinMode(IN1, OUTPUT);\n  pinMode(IN2, OUTPUT);\n}\n\nvoid loop() {\n  if (Serial.available()) {\n    String c = Serial.readStringUntil('\\n');\n    c.trim();\n    if (c.startsWith(\"speed \")) speed = constrain(c.substring(6).toInt(), -255, 255);\n  }\n  digitalWrite(IN1, speed > 0 ? HIGH : LOW);\n  digitalWrite(IN2, speed < 0 ? HIGH : LOW);\n  analogWrite(EN, abs(speed));\n  Serial.print(\"speed=\");\n  Serial.println(speed);\n  delay(200);\n}\n","ldr":"// Photoresistor divider on A1\nvoid setup() {\n  Serial.begin(115200);\n}\n\nvoid loop() {\n  Serial.print(\"light=\");\n  Serial.println(analogRead(A1));\n  delay(100);\n}\n","led":"// LED on D9 through 330 ohm. Send \"on\" or \"off\".\nconst int LED = 9;\nbool on = true;\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(LED, OUTPUT);\n}\n\nvoid loop() {\n  if (Serial.available()) {\n    String c = Serial.readStringUntil('\\n');\n    c.trim();\n    if (c == \"on\") on = true;\n    if (c == \"off\") on = false;\n  }\n  digitalWrite(LED, on ? HIGH : LOW);\n  Serial.print(\"led=\");\n  Serial.println(on ? 1 : 0);\n  delay(200);\n}\n","my_sketch":"// My sketch: edit it in the Code tab of Board Monitor, then Compile & upload.\n// Prints one line of name=value pairs every 200 ms so Board Monitor can plot it,\n// and answers a few text commands sent from the page.\n//\n// Wiring (change to match your build):\n//   A0  potentiometer middle pin\n//   A1  photoresistor + 10k resistor divider\n//   A2  thermistor + 10k resistor divider\n\nconst unsigned long PERIOD_MS = 200;\nunsigned long lastSend = 0;\nbool streaming = true;\nString cmd;\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(LED_BUILTIN, OUTPUT);\n  while (!Serial && millis() < 3000) {}\n  Serial.println(\"UNO R4 ready. Commands: led on, led off, stop, start, help\");\n}\n\nvoid handleCommand(String c) {\n  c.trim();\n  c.toLowerCase();\n  if (c == \"led on\")       { digitalWrite(LED_BUILTIN, HIGH); Serial.println(\"ok led on\"); }\n  else if (c == \"led off\") { digitalWrite(LED_BUILTIN, LOW);  Serial.println(\"ok led off\"); }\n  else if (c == \"stop\")    { streaming = false; Serial.println(\"ok stopped\"); }\n  else if (c == \"start\")   { streaming = true;  Serial.println(\"ok started\"); }\n  else if (c == \"help\")    { Serial.println(\"Commands: led on, led off, stop, start, help\"); }\n  else if (c.length())     { Serial.print(\"unknown command: \"); Serial.println(c); }\n}\n\nvoid loop() {\n  while (Serial.available()) {\n    char ch = Serial.read();\n    if (ch == '\\n' || ch == '\\r') { handleCommand(cmd); cmd = \"\"; }\n    else if (cmd.length() < 64) cmd += ch;\n  }\n\n  if (streaming && millis() - lastSend >= PERIOD_MS) {\n    lastSend = millis();\n    Serial.print(\"pot=\");    Serial.print(analogRead(A0));\n    Serial.print(\",light=\"); Serial.print(analogRead(A1));\n    Serial.print(\",therm=\"); Serial.println(analogRead(A2));\n  }\n}\n","oled":"// SSD1306 OLED on I2C (0x3C). Send \"show <text>\".\n#include <Wire.h>\n#include <Adafruit_GFX.h>\n#include <Adafruit_SSD1306.h>\n\nAdafruit_SSD1306 oled(128, 64, &Wire, -1);\nString msg = \"Hello\";\n\nvoid setup() {\n  Serial.begin(115200);\n  if (!oled.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {\n    Serial.println(\"OLED not found at 0x3C\");\n    while (true) {}\n  }\n}\n\nvoid loop() {\n  if (Serial.available()) {\n    String c = Serial.readStringUntil('\\n');\n    c.trim();\n    if (c.startsWith(\"show \")) msg = c.substring(5);\n  }\n  int a0 = analogRead(A0);\n  oled.clearDisplay();\n  oled.setTextColor(SSD1306_WHITE);\n  oled.setTextSize(2);\n  oled.setCursor(0, 0);\n  oled.println(msg);\n  oled.setTextSize(1);\n  oled.setCursor(0, 48);\n  oled.print(\"A0: \");\n  oled.println(a0);\n  oled.display();\n  Serial.print(\"a0=\");\n  Serial.println(a0);\n  delay(200);\n}\n","pir":"// PIR output on D2\nconst int PIR = 2;\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(PIR, INPUT);\n}\n\nvoid loop() {\n  Serial.print(\"motion=\");\n  Serial.println(digitalRead(PIR));\n  delay(200);\n}\n","pot":"// Potentiometer wiper on A0\nvoid setup() {\n  Serial.begin(115200);\n}\n\nvoid loop() {\n  Serial.print(\"pot=\");\n  Serial.println(analogRead(A0));\n  delay(100);\n}\n","relay":"// Relay module signal on D7. Send \"on\" or \"off\".\nconst int RELAY = 7;\nbool on = false;\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(RELAY, OUTPUT);\n}\n\nvoid loop() {\n  if (Serial.available()) {\n    String c = Serial.readStringUntil('\\n');\n    c.trim();\n    if (c == \"on\") on = true;\n    if (c == \"off\") on = false;\n  }\n  digitalWrite(RELAY, on ? HIGH : LOW);\n  Serial.print(\"relay=\");\n  Serial.println(on ? 1 : 0);\n  delay(200);\n}\n","rfid":"// RC522 RFID: SS on D10, RST on D9, SPI on D11-D13, power from 3.3V\n#include <SPI.h>\n#include <MFRC522.h>\n\nMFRC522 rfid(10, 9);\n\nvoid setup() {\n  Serial.begin(115200);\n  SPI.begin();\n  rfid.PCD_Init();\n  Serial.println(\"Hold a card or fob near the reader\");\n}\n\nvoid loop() {\n  if (!rfid.PICC_IsNewCardPresent() || !rfid.PICC_ReadCardSerial()) return;\n  uint32_t id = 0;\n  for (byte i = 0; i < rfid.uid.size && i < 4; i++) id = (id << 8) | rfid.uid.uidByte[i];\n  Serial.print(\"card=\");\n  Serial.println(id);\n  rfid.PICC_HaltA();\n}\n","rgb":"// RGB LED: red D6, green D5, blue D3, each through 330 ohm\nconst int R = 6, G = 5, B = 3;\nint r = 255, g = 40, b = 0;\n\nvoid setup() {\n  Serial.begin(115200);\n}\n\nvoid loop() {\n  if (Serial.available()) {\n    String c = Serial.readStringUntil('\\n');\n    c.trim();\n    if (c.startsWith(\"rgb \")) sscanf(c.c_str() + 4, \"%d %d %d\", &r, &g, &b);\n  }\n  analogWrite(R, constrain(r, 0, 255));\n  analogWrite(G, constrain(g, 0, 255));\n  analogWrite(B, constrain(b, 0, 255));\n  Serial.print(\"r=\");  Serial.print(r);\n  Serial.print(\",g=\"); Serial.print(g);\n  Serial.print(\",b=\"); Serial.println(b);\n  delay(200);\n}\n","seg1":"// 1-digit common-cathode display: segments a-g, dp on D2-D9 (330 ohm each)\nconst int SEG[8] = {2, 3, 4, 5, 6, 7, 8, 9};   // a b c d e f g dp\nconst byte DIGITS[10] = {0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07, 0x7F, 0x6F};\nint n = 0;\nbool counting = true;\nunsigned long last = 0;\n\nvoid show(int d) {\n  for (int i = 0; i < 7; i++) digitalWrite(SEG[i], (DIGITS[d] >> i) & 1);\n  digitalWrite(SEG[7], LOW);\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  for (int i = 0; i < 8; i++) pinMode(SEG[i], OUTPUT);\n}\n\nvoid loop() {\n  if (Serial.available()) {\n    String c = Serial.readStringUntil('\\n');\n    c.trim();\n    if (c.startsWith(\"show \")) { n = constrain(c.substring(5).toInt(), 0, 9); counting = false; }\n    if (c == \"count\") counting = true;\n  }\n  if (counting && millis() - last > 1000) { last = millis(); n = (n + 1) % 10; }\n  show(n);\n  Serial.print(\"digit=\");\n  Serial.println(n);\n  delay(100);\n}\n","seg4":"// 4-digit common-cathode display: segments on D2-D9 (330 ohm), digits on D10-D13\nconst int SEG[8] = {2, 3, 4, 5, 6, 7, 8, 9};   // a b c d e f g dp\nconst int DIG[4] = {10, 11, 12, 13};\nconst byte DIGITS[10] = {0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07, 0x7F, 0x6F};\nlong value = 1234;\nunsigned long lastPrint = 0;\n\nvoid refresh() {\n  long v = value;\n  byte pat[4];\n  for (int i = 3; i >= 0; i--) { pat[i] = DIGITS[v % 10]; v /= 10; }\n  for (int i = 0; i < 4; i++) {\n    for (int s = 0; s < 7; s++) {\n      if ((pat[i] >> s) & 1) {\n        digitalWrite(DIG[i], LOW);\n        digitalWrite(SEG[s], HIGH);\n        delayMicroseconds(300);\n        digitalWrite(SEG[s], LOW);\n        digitalWrite(DIG[i], HIGH);\n      }\n    }\n  }\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  for (int i = 0; i < 8; i++) { pinMode(SEG[i], OUTPUT); digitalWrite(SEG[i], LOW); }\n  for (int i = 0; i < 4; i++) { pinMode(DIG[i], OUTPUT); digitalWrite(DIG[i], HIGH); }\n}\n\nvoid loop() {\n  if (Serial.available()) {\n    String c = Serial.readStringUntil('\\n');\n    c.trim();\n    if (c.startsWith(\"show \")) value = constrain(c.substring(5).toInt(), 0, 9999);\n  }\n  refresh();\n  if (millis() - lastPrint > 500) {\n    lastPrint = millis();\n    Serial.print(\"value=\");\n    Serial.println(value);\n  }\n}\n","servo":"// SG90 servo signal on D9. Send \"angle <0-180>\".\n#include <Servo.h>\n\nServo servo;\nint angle = 90;\n\nvoid setup() {\n  Serial.begin(115200);\n  servo.attach(9);\n  servo.write(angle);\n}\n\nvoid loop() {\n  if (Serial.available()) {\n    String c = Serial.readStringUntil('\\n');\n    c.trim();\n    if (c.startsWith(\"angle \")) {\n      angle = constrain(c.substring(6).toInt(), 0, 180);\n      servo.write(angle);\n    }\n  }\n  Serial.print(\"angle=\");\n  Serial.println(angle);\n  delay(200);\n}\n","shift595":"// 74HC595: data D12, clock D9, latch D11. Send \"set <0-255>\" or \"run\".\nconst int DATA = 12, CLOCK = 9, LATCH = 11;\nbyte leds = 1;\nbool running = true;\nunsigned long last = 0;\n\nvoid write595(byte b) {\n  digitalWrite(LATCH, LOW);\n  shiftOut(DATA, CLOCK, MSBFIRST, b);\n  digitalWrite(LATCH, HIGH);\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(DATA, OUTPUT);\n  pinMode(CLOCK, OUTPUT);\n  pinMode(LATCH, OUTPUT);\n}\n\nvoid loop() {\n  if (Serial.available()) {\n    String c = Serial.readStringUntil('\\n');\n    c.trim();\n    if (c.startsWith(\"set \")) { leds = constrain(c.substring(4).toInt(), 0, 255); running = false; }\n    if (c == \"run\") running = true;\n  }\n  if (running && millis() - last > 200) {\n    last = millis();\n    leds = (leds << 1) | (leds >> 7);\n    if (leds == 0) leds = 1;\n  }\n  write595(leds);\n  Serial.print(\"leds=\");\n  Serial.println(leds);\n  delay(50);\n}\n","stepper":"// ULN2003: IN1-IN4 on D8-D11. Send \"steps <n>\".\n#include <Stepper.h>\n\nStepper motor(2048, 8, 10, 9, 11);   // order is IN1, IN3, IN2, IN4\nlong pos = 0;\n\nvoid setup() {\n  Serial.begin(115200);\n  motor.setSpeed(10);   // rpm\n}\n\nvoid loop() {\n  if (Serial.available()) {\n    String c = Serial.readStringUntil('\\n');\n    c.trim();\n    if (c.startsWith(\"steps \")) {\n      int n = c.substring(6).toInt();\n      motor.step(n);\n      pos += n;\n    }\n  }\n  Serial.print(\"pos=\");\n  Serial.println(pos);\n  delay(200);\n}\n","thermistor":"// Thermistor divider on A2: 10k from 5V to A2, thermistor from A2 to GND\nconst float R_FIXED = 10000.0, R_NOMINAL = 10000.0, BETA = 3950.0;\n\nvoid setup() {\n  Serial.begin(115200);\n}\n\nvoid loop() {\n  int a = analogRead(A2);\n  if (a < 1) a = 1;\n  if (a > 1022) a = 1022;\n  float rt = R_FIXED * a / (1023.0 - a);\n  float tc = 1.0 / (1.0 / 298.15 + log(rt / R_NOMINAL) / BETA) - 273.15;\n  Serial.print(\"raw=\");     Serial.print(a);\n  Serial.print(\",temp_c=\"); Serial.println(tc, 1);\n  delay(250);\n}\n","tilt":"// Tilt switch on D7, other leg to GND\nconst int TILT = 7;\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(TILT, INPUT_PULLUP);\n}\n\nvoid loop() {\n  Serial.print(\"tilt=\");\n  Serial.println(digitalRead(TILT) == LOW ? 1 : 0);\n  delay(100);\n}\n","ultrasonic":"// HC-SR04: Trig on D12, Echo on D11\nconst int TRIG = 12, ECHO = 11;\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(TRIG, OUTPUT);\n  pinMode(ECHO, INPUT);\n}\n\nvoid loop() {\n  digitalWrite(TRIG, LOW);  delayMicroseconds(2);\n  digitalWrite(TRIG, HIGH); delayMicroseconds(10);\n  digitalWrite(TRIG, LOW);\n  unsigned long us = pulseIn(ECHO, HIGH, 30000);\n  float cm = us / 58.0;\n  Serial.print(\"dist_cm=\");\n  Serial.println(cm, 1);\n  delay(100);\n}\n"};
